+/** Theoretical sales usage and actual consumption per item across inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+
+  const byItem = new Map();
+  const add = (itemId, key, qty) => {
+    if (!byItem.has(itemId)) byItem.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    byItem.get(itemId)[key] += Math.round(qty * 1000);
+  };
+  for (const sale of store.data.sales ?? []) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const { itemId, qty } of sale.ingredients) add(itemId, "theoretical", qty);
+  }
+
+  const batchItems = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || movement.qty <= 0 || !inRange(movement.at)) continue;
+    const itemId = batchItems.get(movement.batchId);
+    if (itemId !== undefined) add(itemId, "actual", movement.qty);
+  }
+
+  return [...byItem.values()]
+    .sort((a, b) => a.itemId - b.itemId)
+    .map(({ itemId, theoretical, actual }) => ({
+      itemId,
+      theoretical: theoretical / 1000,
+      actual: actual / 1000,
+      variance: (actual - theoretical) / 1000,
+    }));
+}
