@@ -0,0 +1,43 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Books new tickets and their recipe usage as one stock operation. */
+export function importSales(store, rows) {
+  const imported = new Set((store.data.sales ?? []).map((sale) => sale.ticket));
+  const pending = rows.filter(({ ticket }) => !imported.has(ticket));
+  if (!pending.length) return { tickets: 0, dishes: 0 };
+
+  const staged = memoryStore(store.data);
+  staged.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { row, ticket, soldAt, dishId, qty } of pending) {
+    let dish;
+    let recipe;
+    try {
+      dish = getDish(staged, dishId);
+      recipe = getRecipe(staged, dish.recipeId);
+    } catch (error) {
+      if (!(error instanceof AppError) || error.code !== "not_found") throw error;
+      throw new AppError("bad_request", { reason: `row ${row}: unknown dish or recipe for dish ${dishId}` });
+    }
+
+    const ingredients = scaled(recipe, qty).filter((ingredient) => ingredient.qty > 0);
+    for (const ingredient of ingredients) {
+      try {
+        consume(staged, ingredient.itemId, ingredient.qty, { at: soldAt, ref: `sale:${ticket}` });
+      } catch (error) {
+        if (!(error instanceof AppError)) throw error;
+        throw new AppError(error.code, { ...error.params, row });
+      }
+    }
+    staged.data.sales.push({ ticket, soldAt, dishId, qty, ingredients });
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
