diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..cd59174
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,40 @@
+import { isDate } from "../dates.js";
+import { importSales } from "../domain/sales.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const csvLine = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:\d{2})$/;
+
+/** Reads and imports a sales CSV, reporting errors by physical row number. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const [header = []] = parseCsv(lines[0]);
+  const keys = header.map((key) => key.trim());
+  if (!csvLine.test(lines[0]) || keys.length !== columns.length || !columns.every((key) => keys.includes(key))) {
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty columns" });
+  }
+  const rows = [];
+  for (const [index, line] of lines.entries()) {
+    if (index === 0 || !line.trim()) continue;
+    const row = index + 1;
+    const [fields] = parseCsv(line);
+    if (!csvLine.test(line) || fields.length !== keys.length) {
+      throw new AppError("bad_request", { reason: `row ${row}: invalid CSV fields` });
+    }
+    const { ticket, soldAt, dishId, qty } = Object.fromEntries(keys.map((key, i) => [key, fields[i].trim()]));
+    if (!ticket) throw new AppError("bad_request", { reason: `row ${row}: ticket is required` });
+    if (!instant.test(soldAt) || !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt))) {
+      throw new AppError("bad_request", { reason: `row ${row}: soldAt must be an ISO instant` });
+    }
+    if (!/^\d+$/.test(dishId) || !Number.isSafeInteger(Number(dishId)) || Number(dishId) < 1) {
+      throw new AppError("bad_request", { reason: `row ${row}: dishId must be a positive whole number` });
+    }
+    if (!/^\d+$/.test(qty) || !Number.isSafeInteger(Number(qty)) || Number(qty) < 1) {
+      throw new AppError("bad_request", { reason: `row ${row}: qty must be a positive whole number` });
+    }
+    rows.push({ row, ticket, soldAt: new Date(soldAt).toISOString(), dishId: Number(dishId), qty: Number(qty) });
+  }
+  return importSales(store, rows);
+}
